import math

def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

def f(x):
    return x * (x**2 + 1) // 2 - 1

print("Checking x from 7 to 30 (odd values):")
solutions = []
for x in range(7, 31, 2):
    y = f(x)
    if is_power_of_two(y):
        solutions.append((x, y))
    print(f"x={x}: f(x) = {y}. Is power of 2: {is_power_of_two(y)}")

print("\nSolutions found for x > 5 (odd):", solutions)

def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

n_values = [5, 6]
x_values = [13, 17, 21, 25, 29] # Checking a small range of x congruent to 1 mod 4
solutions = []

for n in n_values:
    for x in x_values:
        if x <= n:
            continue

        lhs_val = x**n + x
        rhs_target = lhs_val - 2

        if is_power_of_two(rhs_target):
            # If it's a power of two, say 2^k, then k = log2(rhs_target)
            # We must ensure k >= 1, which is true if rhs_target >= 2.
            # Since x >= 13 and n >= 5, rhs_target is much larger than 2.

            # Find k explicitly just in case, although the problem only asks for checking solutions
            import math
            k = int(math.log2(rhs_target))
            solutions.append((x, n, k))

print("Solutions found for specified constraints:")
for s in solutions:
    print(s)
